//! Four continuously running actual Nodes perform bootstrap rotation and their
//! own provider install/ACK. All quorum votes are generated by those workers.
//! Noise/native TCP are real; issuer witness, memory backend/key handles and
//! elapsed clock remain test doubles, not independent physical custody.
use super::bootstrap_rotation_cases::{handoff_bootstrap, make_body, signed};
use super::rotation_live_support::{FourLiveRotationNodes, diagnostics, public, wait_until};
use super::*;
use std::sync::atomic::Ordering;

#[test]
fn wire3_four_live_bootstrap_nodes_install_new_key_and_require_its_quorum_vote() {
    thread::Builder::new()
        .stack_size(32 * 1024 * 1024)
        .spawn(live_rotation)
        .unwrap()
        .join()
        .unwrap();
}
fn live_rotation() {
    let h = handoff_bootstrap();
    let mut fixture = FourLiveRotationNodes::new(&h, 4, 6, None);
    let immutable = fixture
        .actual
        .iter()
        .map(|d| {
            let d = d.lock().unwrap();
            let w = d.world();
            assert!(w.state().governance_validator_admissions.is_empty());
            (
                serde_cbor::to_vec(&w.state().governance_finality_signer_registry).unwrap(),
                serde_cbor::to_vec(&w.state().governance_validator_admissions).unwrap(),
                w.node_identity_public_key(&validator_id(3))
                    .map(str::to_owned),
                w.node_main_token_account(&validator_id(3))
                    .map(str::to_owned),
            )
        })
        .collect::<Vec<_>>();
    fixture.start();
    let FourLiveRotationNodes {
        mut nodes,
        actual,
        bindings,
        snapshots,
        origin,
        healed,
        old_calls,
        new_calls,
        servers,
        stage_budget,
        _roots,
        _stores,
        _networks,
    } = fixture;
    let deadline = Instant::now() + stage_budget;
    let diagnostic = || diagnostics(&bindings, &snapshots, &origin);
    wait_until(
        deadline,
        &nodes,
        "all actual Nodes retain qualified h3",
        &diagnostic,
        || {
            nodes
                .iter()
                .all(|n| n.bft_v3_status().unwrap().committed_height == 3)
                && snapshots.iter().all(|s| {
                    s.lock()
                        .unwrap()
                        .state
                        .history
                        .last()
                        .is_some_and(|c| c.execution_commitment.height == 3)
                })
        },
    );
    let mut schedule = bindings[3].initial_schedule().clone();
    let certified = snapshots[3]
        .lock()
        .unwrap()
        .state
        .history
        .last()
        .unwrap()
        .clone();
    let tip = verify_commit_certificate_token_v3(&schedule, &certified).unwrap();
    schedule = tip.next_height_schedule().clone();
    assert_eq!(schedule.height(), 4);
    let body = make_body(&actual[3], &tip, 0, 4);
    let proofs = nodes[3]
        .request_bft_v3_bootstrap_finality_key_rotation_proofs(
            body.clone(),
            Duration::from_secs(120),
        )
        .unwrap();
    let (id, action_payload) = signed(&body, proofs, 31004);
    // Same original private action, independently checked by all real ingress
    // hooks. Nothing is inserted into public gossip or a driver's private map.
    for n in &nodes {
        n.submit_consensus_action_payload(id, action_payload.clone())
            .unwrap();
    }
    wait_until(
        Instant::now() + stage_budget,
        &nodes,
        "all live Node install workers ACK h6 key",
        &diagnostic,
        || {
            snapshots.iter().all(|s| {
                s.lock()
                    .unwrap()
                    .state
                    .membership_install
                    .as_ref()
                    .is_some_and(|m| m.receipts.iter().any(|r| r.body.activation_height == 6))
            })
        },
    );
    eprintln!("bootstrap live installed checkpoints:\n{}", diagnostic());
    let retired_count = old_calls.load(Ordering::SeqCst);
    wait_until(
        Instant::now() + stage_budget,
        &nodes,
        "actual nodes1/2/3 commit necessary new-key quorum",
        &diagnostic,
        || {
            snapshots[1..].iter().all(|s| {
                s.lock()
                    .unwrap()
                    .state
                    .history
                    .last()
                    .is_some_and(|c| c.execution_commitment.height >= 6)
            })
        },
    );
    {
        let snapshot = snapshots[3].lock().unwrap();
        let qc = snapshot
            .state
            .history
            .iter()
            .find(|c| c.execution_commitment.height == 6)
            .unwrap();
        assert_eq!(qc.certificate.precommits.len(), 3);
        assert!(
            qc.certificate
                .precommits
                .iter()
                .any(|v| v.validator_id == validator_id(3) && v.public_key_hex == public(124))
        );
        assert!(
            !qc.certificate
                .precommits
                .iter()
                .any(|v| v.validator_id == validator_id(0))
        );
    }
    healed.store(true, Ordering::Release);
    wait_until(
        Instant::now() + stage_budget,
        &nodes,
        "all four live Nodes recover the new-key head",
        &diagnostic,
        || {
            snapshots.iter().all(|s| {
                s.lock()
                    .unwrap()
                    .state
                    .history
                    .last()
                    .is_some_and(|c| c.execution_commitment.height >= 6)
            })
        },
    );
    for n in &nodes {
        n.submit_consensus_action_payload(31007, payload("bootstrap-live-healed-continued"))
            .unwrap();
    }
    wait_until(
        Instant::now() + stage_budget,
        &nodes,
        "legal action after healed new-key quorum",
        &diagnostic,
        || {
            actual.iter().all(|d| {
                d.lock()
                    .unwrap()
                    .world()
                    .state()
                    .agents
                    .contains_key("bootstrap-live-healed-continued")
            })
        },
    );
    assert_eq!(
        old_calls.load(Ordering::SeqCst),
        retired_count,
        "retired handle must not sign after Node install ACK"
    );
    assert!(new_calls.load(Ordering::SeqCst) > 0);
    for n in &mut nodes {
        assert!(n.bft_v3_status().unwrap().running);
        n.stop().unwrap();
    }
    for (index, snapshot) in snapshots.iter().enumerate() {
        let state = &snapshot.lock().unwrap().state;
        let receipt = state
            .membership_install
            .as_ref()
            .unwrap()
            .receipts
            .iter()
            .find(|r| r.body.activation_height == 6)
            .unwrap();
        assert_eq!(receipt.body.source_height, 4);
        assert_eq!(
            receipt.body.local_signing_public_key,
            public(if index == 3 { 124 } else { 120 + index as u8 })
        );
        let decision = state
            .history
            .iter()
            .find(|c| c.execution_commitment.height == 4)
            .unwrap();
        assert!(
            decision.certificate.proposal.round >= 1,
            "real dropped round0 must recover through consensus timers"
        );
        let confirmation = state
            .history
            .iter()
            .find(|c| c.execution_commitment.height == 5)
            .unwrap();
        assert!(
            confirmation
                .certificate
                .precommits
                .iter()
                .all(|v| v.validator_id != validator_id(3) || v.public_key_hex == public(123))
        );
        if index == 3 {
            for journal in state
                .completed_journals
                .iter()
                .flatten()
                .filter(|j| j.height == 4 || j.height == 5)
            {
                assert_eq!(journal.local_signing_public_key(), public(123));
            }
            let qc = state
                .history
                .iter()
                .find(|c| c.execution_commitment.height == 6)
                .unwrap();
            assert_eq!(qc.certificate.precommits.len(), 3);
            assert!(
                qc.certificate
                    .precommits
                    .iter()
                    .any(|v| v.validator_id == validator_id(3) && v.public_key_hex == public(124))
            );
            assert!(
                !qc.certificate
                    .precommits
                    .iter()
                    .any(|v| v.validator_id == validator_id(0))
            );
            for journal in state
                .completed_journals
                .iter()
                .flatten()
                .chain(state.journal.iter())
                .filter(|j| j.height >= 6)
            {
                assert_eq!(journal.local_signing_public_key(), public(124));
            }
        }
        let d = actual[index].lock().unwrap();
        let w = d.world();
        assert_eq!(
            serde_cbor::to_vec(&w.state().governance_finality_signer_registry).unwrap(),
            immutable[index].0
        );
        assert_eq!(
            serde_cbor::to_vec(&w.state().governance_validator_admissions).unwrap(),
            immutable[index].1
        );
        assert_eq!(
            w.node_identity_public_key(&validator_id(3)),
            immutable[index].2.as_deref()
        );
        assert_eq!(
            w.node_main_token_account(&validator_id(3)),
            immutable[index].3.as_deref()
        );
        assert_eq!(
            w.state().governance_bootstrap_finality_key_rotations.len(),
            1
        );
    }
    for server in servers {
        server.join().unwrap().unwrap();
    }
}
